"use client"

import { useState, useEffect } from "react"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Wallet, RefreshCw } from "lucide-react"
import { useAppStore } from "@/lib/store"

export function WalletBalanceWidget() {
  const [lastUpdated, setLastUpdated] = useState<Date>(new Date())
  const [isRefreshing, setIsRefreshing] = useState(false)
  const currentUser = useAppStore((state) => state.currentUser)

  const balance = currentUser?.walletBalance || 2543000

  const handleRefresh = async () => {
    setIsRefreshing(true)
    // Simulate API call
    await new Promise((resolve) => setTimeout(resolve, 1000))
    setLastUpdated(new Date())
    setIsRefreshing(false)
  }

  const getMinutesAgo = () => {
    const diff = Math.floor((new Date().getTime() - lastUpdated.getTime()) / 1000 / 60)
    if (diff < 1) return "Just now"
    if (diff === 1) return "1 minute ago"
    return `${diff} minutes ago`
  }

  return (
    <Card className="bg-primary text-primary-foreground">
      <CardHeader className="pb-2">
        <div className="flex items-center justify-between">
          <CardTitle className="text-lg font-medium opacity-90">Wallet Balance</CardTitle>
          <Button
            variant="ghost"
            size="icon"
            className="h-8 w-8 text-primary-foreground hover:bg-primary-foreground/20"
            onClick={handleRefresh}
            disabled={isRefreshing}
          >
            <RefreshCw className={`h-4 w-4 ${isRefreshing ? "animate-spin" : ""}`} />
          </Button>
        </div>
      </CardHeader>
      <CardContent>
        <div className="flex items-center gap-2">
          <Wallet className="h-6 w-6 opacity-75" />
          <div className="text-4xl font-bold">₹{balance.toLocaleString("en-IN")}</div>
        </div>
        <p className="mt-2 text-sm opacity-75">Updated {getMinutesAgo()}</p>
      </CardContent>
    </Card>
  )
}

